import pandas as pdfrom datetime import datetime, timedeltafrom pathlib import Path# ==== USER SETTING: folder with all your Excel files ====folder_path = Path("/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/eugene_daylight_hours/")# List to hold all records from all monthsall_records = []# Loop over matching Excel filesfor file_path in sorted(folder_path.glob("*eugene-oregon-usa-sunrise-and-sunset-calendar-bluegrey-sunday-start-en.xlsx")):    print(f"Processing file: {file_path.name}")        # Extract year and month from filename    filename_parts = file_path.name.split("-")    try:        year = int(filename_parts[0])        month_number = int(filename_parts[1])    except (ValueError, IndexError):        print(f"Could not parse year/month from filename: {file_path.name}")        continue    # Load the Excel sheet    df = pd.read_excel(file_path, sheet_name=None, header=None)    sheet_name = list(df.keys())[0]    df = df[sheet_name]    # List to store records for this file    records = []    # Iterate over all cells    for col in range(df.shape[1]):        row = 0        while row < df.shape[0]:            date_cell = df.iloc[row, col]            if pd.isna(date_cell):                row += 1                continue            try:                day_of_month = int(date_cell)            except (ValueError, TypeError):                row += 1                continue            if not (1 <= day_of_month <= 31):                row += 1                continue            # Info cell: prefer cell below            info_cell = None            if row + 1 < df.shape[0]:                info_cell = df.iloc[row + 1, col]            if pd.isna(info_cell):                # Try cell to the right                if col + 1 < df.shape[1]:                    info_cell = df.iloc[row, col + 1]            if pd.isna(info_cell) or not isinstance(info_cell, str) or "Sunrise" not in info_cell:                row += 1                continue            # Parse info            info_lines = str(info_cell).split("\n")            sunrise = ""            sunset = ""            daylight = ""            for line in info_lines:                line = line.strip()                if line.startswith("Sunrise:"):                    sunrise = line.replace("Sunrise:", "").strip()                elif line.startswith("Sunset:"):                    sunset = line.replace("Sunset:", "").strip()                elif line.startswith("Daylight:"):                    daylight = line.replace("Daylight:", "").strip()            date_str = datetime(year, month_number, day_of_month).strftime("%m-%d-%Y")            records.append({                "Date": date_str,                "Sunrise": sunrise,                "Sunset": sunset,                "Daylight": daylight            })            row += 2    all_records.extend(records)# === Create combined DataFrame ===calendar_df = pd.DataFrame(all_records)# === Convert Daylight to HH:MM with leading zeros ===def daylight_to_hhmm(daylight_str):    if pd.isna(daylight_str):        return ""    parts = daylight_str.lower().replace(".", "").split(" and ")    hours = 0    minutes = 0    for part in parts:        if "hour" in part:            hours = int(part.strip().split()[0])        elif "minute" in part:            minutes = int(part.strip().split()[0])    return f"{hours:02d}:{minutes:02d}"calendar_df["Daylight"] = calendar_df["Daylight"].apply(daylight_to_hhmm)# === Convert Date to datetime and sort ===calendar_df["Date_dt"] = pd.to_datetime(calendar_df["Date"], format="%m-%d-%Y")calendar_df = calendar_df.sort_values("Date_dt").reset_index(drop=True)calendar_df = calendar_df.drop(columns=["Date_dt"])# === Function to round times to nearest 15 min ===def round_time_str_to_nearest_15min(time_str):    if pd.isna(time_str) or not isinstance(time_str, str) or time_str.strip() == "":        return ""    try:        t = datetime.strptime(time_str, "%I:%M %p")        total_minutes = t.hour * 60 + t.minute        rounded_minutes = int(round(total_minutes / 15.0) * 15)        if rounded_minutes == 1440:            rounded_minutes = 0        hour = rounded_minutes // 60        minute = rounded_minutes % 60        rounded_time = datetime(1900, 1, 1, hour, minute)        return rounded_time.strftime("%-I:%M %p")    except Exception as e:        print(f"Error parsing time: {time_str} - {e}")        return time_str# === Create rounded DataFrame ===rounded_calendar_df = calendar_df.copy()rounded_calendar_df["Sunrise"] = rounded_calendar_df["Sunrise"].apply(round_time_str_to_nearest_15min)rounded_calendar_df["Sunset"] = rounded_calendar_df["Sunset"].apply(round_time_str_to_nearest_15min)# Create DataFrame of unique Sunrise/Sunset combinations with earliest dateunique_times_df = (    rounded_calendar_df    .groupby(["Sunrise", "Sunset"])    .agg({"Date": "min"})    .reset_index())# Sort by earliest dateunique_times_df["Date_dt"] = pd.to_datetime(unique_times_df["Date"], format="%m-%d-%Y")unique_times_df = unique_times_df.sort_values("Date_dt").reset_index(drop=True)unique_times_df = unique_times_df.drop(columns=["Date_dt"])# Displayprint(unique_times_df)# Displayprint(unique_times_df)# Display the resultprint(unique_times_df)# === Display results ===print("\n=== Original Times ===")print(calendar_df)print("\n=== Rounded Times ===")print(rounded_calendar_df)# === Optionally save ===# calendar_df.to_csv("Combined_Sunrise_Sunset.csv", index=False)# rounded_calendar_df.to_csv("Combined_Sunrise_Sunset_Rounded.csv", index=False)